class Time {
    _step;
    _hours;
    _days;
    constructor() {
        this._step = 0;
        this._hours = 0;
        this._days = 0;
    }
    getDays() {
        return this._days;
    }
    addHours(steps = 1) {
        this._step += steps;
        this._days = Math.floor(this._step / 24);
    }
    subHours(steps = 1) {
        this._step -= steps;
        this._days = Math.floor(this._step / 24);
    }
    getHours() {
        return this._step;
    }
}
export default Time;
