class GameObjects {
    _time;
    _player;
    _history; //TODO 
    constructor(time, player, history = 'todo') {
        this._time = time;
        this._player = player;
        this._history = history;
    }
    getTime() {
        return this._time;
    }
    getPlayer() {
        return this._player;
    }
    getHistory() {
        return this._history;
    }
}
export default GameObjects;
